import gurobipy as gp

# Data
data = {'supply': [[20, 30], [40, 10]], 'demand': [[30, 30], [30, 10]], 'limit': [[35, 25], [20, 30]], 'cost': [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]}

